                    ['q' => "Pourquoi ne choisit-on pas un matériau seulement parce qu’il est recyclable ?", 'c' => ["Fabrication, usage et durée de vie pèsent aussi dans le bilan", "Recyclable signifie biodégradable en quelques semaines dans la nature", "Un matériau recyclable n’a aucun impact au moment de sa fabrication", "Le recyclage est impossible pour la plupart des métaux usuels"], 'a' => 0, 'e' => "Le recyclage n’est qu’une étape. Une pièce fragile qui dure peu peut avoir plus d’impact qu’une pièce durable non recyclée."],
                    ['q' => "Pourquoi alléger un véhicule peut-il réduire sa consommation ?", 'c' => ["La traînée aérodynamique disparaît dès que la masse diminue sensiblement", "Mettre en mouvement une masse plus faible demande moins d’énergie", "Un véhicule léger n’a plus besoin de freiner, donc il économise du carburant", "Le réservoir se vide moins vite parce que le carburant y est plus dense"], 'a' => 1, 'e' => "L’énergie cinétique vaut ½mv² : à vitesse égale, moins de masse demande moins d’énergie."],
                    ['q' => "Le matériau A coûte 100 € et dure 10 ans ; le B coûte 60 € et dure 4 ans. Lequel est le moins cher par année de service ?", 'c' => ["B, à 15 € par an", "B, car 60 est inférieur à 100", "A, à 100 € par an", "A, à 10 € par an"], 'a' => 3, 'e' => "A : 100 / 10 = 10 €/an ; B : 60 / 4 = 15 €/an. Comparer le seul prix d’achat est trompeur."],
                    ['q' => "Pourquoi prolonger la durée de vie d’une pièce a-t-il un intérêt environnemental ?", 'c' => ["L’impact de la fabrication est partagé sur plus d’années", "On augmente la quantité de déchets produits chaque année par la pièce", "On évite d’entretenir la pièce et de la réparer en cours d’usage", "On supprime l’étape de recyclage, qui pollue plus que la fabrication"], 'a' => 0, 'e' => "Fabriquer moins souvent de nouvelles pièces économise matières premières et énergie."],
